-- DEC-049: preserve historical rows and snapshots; no destructive backfill.
ALTER TABLE events ADD COLUMN delivery_name VARCHAR(160) NOT NULL DEFAULT '';
ALTER TABLE events ADD COLUMN delivery_directions VARCHAR(500) NOT NULL DEFAULT '';
ALTER TABLE events MODIFY COLUMN encounter_words VARCHAR(5000) NOT NULL;
ALTER TABLE event_meeting_points ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE event_activities ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE participants ADD COLUMN avatar_animal VARCHAR(16) NOT NULL DEFAULT 'gato';
ALTER TABLE participants ADD COLUMN avatar_hat VARCHAR(16) NOT NULL DEFAULT 'none';
ALTER TABLE participants ADD COLUMN avatar_accessory VARCHAR(16) NOT NULL DEFAULT 'none';
ALTER TABLE participants ADD COLUMN avatar_background VARCHAR(16) NOT NULL DEFAULT 'violeta';
ALTER TABLE benefits ADD COLUMN default_delivery BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE interests ADD COLUMN stable_key VARCHAR(100) NULL UNIQUE;
CREATE TABLE interest_nodes(node_key VARCHAR(100) PRIMARY KEY, label VARCHAR(80) NOT NULL, parent_key VARCHAR(100) NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE interest_node_members(node_key VARCHAR(100) NOT NULL, interest_id BIGINT NOT NULL, PRIMARY KEY(node_key,interest_id), FOREIGN KEY(node_key) REFERENCES interest_nodes(node_key), FOREIGN KEY(interest_id) REFERENCES interests(id));
